from collections import Counter
G=load(); print(sorted(G))
for pair in ['Demo pair 1','Demo pair 2']:
    inp=G[pair+' input']; out=G[pair+' output']
    s=sum(sum(r) for r in out)
    tot=Counter()
    for i in range(len(inp)-2):
        for j in range(len(inp[0])-2):
            w=[row[j:j+3] for row in inp[i:i+3]]
            tot[tuple(tuple(r) for r in w)]+=1
    same={k for k,v in tot.items() if sum(sum(r) for r in k)==s}
    print(pair,'sum',s,'windows with that sum:',len(same),'target count',tot.get(tuple(map(tuple,out))), 'sample:',list(same)[:4])

